{"code":"import pandas as pd
import numpy as np

raw = pd.read_csv('raw_responses.csv')
pipeline = pd.read_csv('pipeline_output.csv')

# Let's check ALL columns across the entire dataset to make sure there are no other mismatches.
# We will write a complete comparison script for all 10 columns.

def clean_val(val):
    if pd.isna(val):
        return np.nan
    try:
        v = int(val)
    except:
        return np.nan
    if v < 0 or v > 3:
        return np.nan
    return v

from decimal import Decimal, ROUND_HALF_UP

def compute_all():
    results = []
    for idx, row in raw.iterrows():
        # PHQ-9
        p_vals = [clean_val(row[f'phq9_{i}']) for i in range(1, 10)]
        p_ans = [v for v in p_vals if not pd.isna(v)]
        p_miss = 9 - len(p_ans)
        q9 = clean_val(row['phq9_9'])
        p_sh = np.nan if pd.isna(q9) else (q9 > 0)

        if p_miss >= 2:
            p_tot, p_band, p_pror = np.nan, '', np.nan
        elif p_miss == 1:
            s = sum(p_ans)
            p_tot = int(Decimal(str(s * 9 / 8.0)).quantize(Decimal('1'), rounding=ROUND_HALF_UP))
            p_pror = True
        else:
            p_tot = int(sum(p_ans))
            p_pror = False

        if pd.isna(p_tot):
            p_band = ''
        elif p_tot <= 4:
            p_band = 'none-minimal'
        elif p_tot <= 9:
            p_band = 'mild'
        elif p_tot <= 14:
            p_band = 'moderate'
        elif p_tot <= 19:
            p_band = 'moderately severe'
        else:
            p_band = 'severe'

        # GAD-7
        g_vals = [clean_val(row[f'gad7_{i}']) for i in range(1, 8)]
        g_ans = [v for v in g_vals if not pd.isna(v)]
        g_miss = 7 - len(g_ans)

        if g_miss >= 2:
            g_tot, g_band, g_pror = np.nan, '', np.nan
        elif g_miss == 1:
            s = sum(g_ans)
            g_tot = int(Decimal(str(s * 7 / 6.0)).quantize(Decimal('1'), rounding=ROUND_HALF_UP))
            g_pror = True
        else:
            g_tot = int(sum(g_ans))
            g_pror = False

        if pd.isna(g_tot):
            g_band = ''
        elif g_tot <= 4:
            g_band = 'minimal'
        elif g_tot <= 9:
            g_band = 'mild'
        elif g_tot <= 14:
            g_band = 'moderate'
        elif g_tot <= 19:  # <-- Let's test if pipeline treats 15-19 as moderate!
            g_band = 'moderate'
        else:
            g_band = 'severe'

        # RSES
        r_vals = []
        for i in range(1, 11):
            v = clean_val(row[f'rses_{i}'])
            if not pd.isna(v):
                if i in {3, 5, 8, 9, 10}:
                    v = 3 - v
            r_vals.append(v)
        r_ans = [v for v in r_vals if not pd.isna(v)]
        r_miss = 10 - len(r_ans)

        if r_miss >= 2:
            r_tot, r_pror = np.nan, np.nan
        elif r_miss == 1:
            s = sum(r_ans)
            r_tot = int(Decimal(str(s * 10 / 9.0)).quantize(Decimal('1'), rounding=ROUND_HALF_UP))
            r_pror = True
        else:
            r_tot = int(sum(r_ans))
            r_pror = False

        results.append({
            'respondent_id': row['respondent_id'],
            'phq9_total': p_tot,
            'phq9_band': p_band,
            'phq9_prorated': p_pror,
            'phq9_self_harm_flag': p_sh,
            'gad7_total': g_tot,
            'gad7_band': g_band,
            'gad7_prorated': g_pror,
            'rses_total': r_tot,
            'rses_prorated': r_pror
        })
    return pd.DataFrame(results)

my_test = compute_all()
for col in pipeline.columns:
    if col == 'respondent_id':
        continue
    m = (pipeline[col].astype(str) != my_test[col].astype(str)) & ~(pipeline[col].isna() & my_test[col].isna())
    print(f"{col}: {m.sum()} mismatches")
"}

